function groupIdenticalFiles(dirs: string[]): string[][] {
  const files: [string, string][] = [];
  for (const line of dirs) {
    const [folder, ...rest] = line.split(" ");
    for (const f of rest) {
      const p = f.indexOf("(");
      files.push([folder + "/" + f.slice(0, p), f.slice(p + 1, -1)]);
    }
  }
  const taken = new Array(files.length).fill(false);
  const out: string[][] = [];
  for (let i = 0; i < files.length; i++) {
    if (taken[i]) continue;
    const group = [files[i][0]];
    for (let j = i + 1; j < files.length; j++) {
      if (!taken[j] && files[j][1] === files[i][1]) { taken[j] = true; group.push(files[j][0]); }
    }
    if (group.length > 1) out.push(group);
  }
  return out;
}

