function groupIdenticalFiles(dirs: string[]): string[][] {
  const byContent = new Map<string, string[]>();
  for (const line of dirs) {
    const parts = line.split(" ");
    const folder = parts[0];
    for (let i = 1; i < parts.length; i++) {
      const f = parts[i], p = f.indexOf("(");
      const content = f.slice(p + 1, -1);
      if (!byContent.has(content)) byContent.set(content, []);
      byContent.get(content)!.push(folder + "/" + f.slice(0, p));
    }
  }
  return [...byContent.values()].filter(g => g.length > 1);
}

